function da_read_json($path,$label){if(!is_file($path)||!is_readable($path)||is_link($path))throw new InvalidArgumentException($label.' is missing or unsafe.');$s=filesize($path);if(false===$s||$s<2||$s>16777216)throw new InvalidArgumentException($label.' size is invalid.');$bytes=file_get_contents($path);if(!is_string($bytes)||strlen($bytes)!==$s)throw new RuntimeException($label.' could not be read exactly.');$v=json_decode($bytes,true);if(!is_array($v)||JSON_ERROR_NONE!==json_last_error())throw new InvalidArgumentException($label.' JSON is invalid.');return $v;}
function da_version($root){$bytes=file_get_contents($root.'/certloom.php');if(!is_string($bytes)||1!==preg_match("/define\\(\\s*'ECAPLA_CERTVERIFY_VERSION'\\s*,\\s*'([^']+)'\\s*\\)/",$bytes,$m))throw new RuntimeException('Could not determine Certloom source version.');return trim($m[1]);}
function da_external_dir($path,$root,$must_exist){$raw=(string)$path;if(''===$raw)throw new InvalidArgumentException('External directory is required.');$parent=$must_exist?$raw:dirname($raw);$real=realpath($parent);if(false===$real||!is_dir($real)||is_link($real))throw new InvalidArgumentException('External directory parent is invalid or symbolic.');$source=realpath($root);if($real===$source||0===strpos($real,rtrim($source,'/\\').DIRECTORY_SEPARATOR))throw new InvalidArgumentException('DBAUTH evidence/output must remain outside the Certloom source tree.');if($must_exist){$dir=realpath($raw);if(false===$dir||!is_dir($dir)||is_link($dir))throw new InvalidArgumentException('Acceptance directory is invalid or symbolic.');return rtrim($dir,'/\\');}if(file_exists($raw))throw new InvalidArgumentException('Authority output directory must not already exist.');return rtrim($raw,'/\\');}
function da_rrmdir($path){if(!is_dir($path)||is_link($path))return;foreach(scandir($path)?:array() as $leaf){if('.'===$leaf||'..'===$leaf)continue;$full=$path.DIRECTORY_SEPARATOR.$leaf;if(is_dir($full)&&!is_link($full))da_rrmdir($full);else @unlink($full);}@rmdir($path);}
try{$root=dirname(__DIR__,2);$in=da_external_dir($argv[1],$root,true);$out=da_external_dir($argv[2],$root,false);$actual=array_values(array_filter(scandir($in)?:array(),fn($x)=>$x!=='.'&&$x!=='..'));sort($actual,SORT_STRING);if($actual!==array('acceptance-index.json','normalized-domain-acceptance.json'))throw new InvalidArgumentException('Acceptance directory must contain exactly normalized-domain-acceptance.json and acceptance-index.json.');$bundle=da_read_json($in.'/normalized-domain-acceptance.json','Normalized-domain acceptance bundle');$idx=da_read_json($in.'/acceptance-index.json','Normalized-domain acceptance index');$importer=new DomainAcceptanceImporter();$imported=$importer->import($bundle,$idx);$runtime=(new RuntimePayloadFingerprint())->fingerprint($root);$version=da_version($root);if($imported['bundle']['plugin_version']!==$version||$imported['bundle']['runtime_payload']!==$runtime)throw new InvalidArgumentException('Normalized-domain acceptance evidence does not target this exact Certloom production payload/version.');$manifest=(new DomainReleaseManifest())->from_imported_acceptance($imported);$canonical=new CanonicalJson();$authority_index=array('schema'=>'certloom-domain-authority-finalization','version'=>1,'plugin_version'=>$version,'runtime_payload'=>$runtime,'acceptance_sha256'=>$imported['acceptance_sha256'],'acceptance_index_sha256'=>$imported['index_sha256'],'release_manifest_sha256'=>(new DomainReleaseManifest())->hash($manifest),'environment_sha256'=>$imported['bundle']['environment_sha256'],'domain_state_sha256'=>$imported['bundle']['domain_state_sha256']);$parent=dirname($out);$stage=$parent.'/.certloom-domain-authority.'.bin2hex(random_bytes(12));if(!mkdir($stage,0700))throw new RuntimeException('Could not create private DBAUTH finalization stage.');try{$files=array('normalized-domain-acceptance.json'=>$canonical->encode($imported['bundle'])."\n",'acceptance-index.json'=>$canonical->encode($imported['index'])."\n",'accepted.json'=>(new DomainReleaseManifest())->encode($manifest)."\n",'authority-index.json'=>$canonical->encode($authority_index)."\n");foreach($files as $name=>$bytes){$path=$stage.'/'.$name;if(false===file_put_contents($path,$bytes,LOCK_EX)||!chmod($path,0600))throw new RuntimeException('Could not write protected DBAUTH finalization evidence: '.$name);}if(!rename($stage,$out))throw new RuntimeException('Could not atomically publish DBAUTH authority directory.');$stage='';}finally{if(isset($stage)&&''!==$stage)da_rrmdir($stage);}echo "PASS  normalized-domain DBAUTH authority finalized for exact Certloom production payload\n";}catch(Throwable $e){fwrite(STDERR,'FAIL  '.$e->getMessage()."\n");exit(1);}
